export function printerInstructions(session: PrinterSessionPayload): string {
  const { context } = session;
  const adding = session.mode === 'add';
  let text =
    (adding ? GOAL_ADDING + CONDUCT : GOAL_THEIRS + CONDUCT + SCOPE) +
    CHOICES +
    (adding ? FINDING_EXAMPLES + FINDING : '\n') +
    changing(adding) +
    (adding ? '' : SETTINGS) +
    connecting(adding) +
    FINISHING;
  if (session.mode === 'add') text += '\nThe person is adding a printer.\n';
  // Said outright: left to the facts, "Connected to this app: no" read as not
  // set up yet, and the model offered to add a printer the person already had.
  const alreadySetUp = 'This printer is already set up in this app: they can prepare prints for it now, connected or not.';
  if (session.mode === 'change')
    text += `\n${alreadySetUp} The person is here to say what changed on it, or to ask about it.\n`;
  if (session.mode === 'connect') text += `\n${alreadySetUp} The person is here to connect it.\n`;
  if ((context.network ?? []).length > 0)
    text += 'Printers the app knows of now: ' + context.network!.map((found) => `${found.name} (${found.serial})`).join(', ') + '\n';
  const printer = context.printer;
  if (printer) {
    text += `\nThe printer this is about:\nName: ${printer.name}\n`;
    if (printer.stock)
      text +=
        'Kind: the settings JusPrin comes with for this model, selected in the project, not a printer the person ' +
        'added. Its nozzle size and connection are not saved here, and a change to its settings is saved as a copy.\n' +
        `Copy to save as: ${printer.copyName}\n`;
    if (printer.model) text += `Brand and model: ${printer.model}\n`;
    text += `Nozzle: ${printer.nozzle > 0 ? `${numberText(printer.nozzle)} mm` : 'unknown'}`;
    if (printer.nozzles.length > 0) text += ` (this model ships ${sizesText(printer.nozzles)})`;
    // Only a connected printer says what it holds; nothing stands in for it.
    text += '\nLoaded, as the printer reports it:';
    if (!printer.connected) text += ' not known, as it is not connected';
    else if (printer.provider !== 'bambu') text += ' not known, as a Moonraker or OctoPrint connection does not report it';
    else if (printer.spools.length === 0) text += ' nothing';
    for (const spool of printer.spools)
      text += `\n- ${spool.name || spool.material} (${spool.material}${spool.colour ? `, ${spool.colour}` : ''})`;
    text += `\nConnected to this app: ${printer.connected ? 'yes' : 'no'}\n`;
    text += `Connects through: ${printer.provider === 'bambu' ? 'Bambu Lab LAN mode' : 'Moonraker or OctoPrint'}\n`;
    if (printer.needsNetworkPlugin)
      text +=
        "Bambu's network plug-in: not loaded, so nothing can reach this printer yet. The app has shown the person how to " +
        'install it.\n';
  }
  if (context.printers) {
    text += '\nPrinter list (catalogId | brand and model | build volume):\n';
    for (const [id, name, volume] of context.printers) text += `${id} | ${name} | ${volume || '?'}\n`;
  }
  return text;
}

import { loadSkills } from './skillParser';
export { loadSkills, parseSkill, type Skill } from './skillParser';

// Every skills/<name>/SKILL.md, bundled with the page and sent to the app
// once per connection with the skills message.
const skillFiles = import.meta.glob('./skills/*/SKILL.md', {
  query: '?raw',
  import: 'default',
  eager: true,
}) as Record<string, string>;

export const skills = loadSkills(skillFiles);
// A project skill is text for one kind of situation. The page writes each one
// as skills/<name>/SKILL.md: YAML frontmatter, then the body, which is the
// text the model gets. A skill with a `trigger` is added by the app to one
// request when the event it names happens; the model does not choose it. A
// skill with a `description` is listed for the model, which reads it with
// skill_read when the description fits. A skill may have both.
export interface Skill {
  name: string;
  trigger?: string;
  description?: string;
  text: string;
}

const SKILL_NAME = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
const TRIGGER = /^[a-z]+(?:_[a-z]+)*$/;
const FRONTMATTER = /^---\n([\s\S]*?)\n---(?:\n|$)/;
// The app refuses a longer text (AgentHost, Protocol::kSkills).
export const SKILL_TEXT_LIMIT = 16 * 1024;
const encoder = new TextEncoder();

function scalar(raw: string, source: string): string {
  if (raw.startsWith('"')) {
    try {
      const value: unknown = JSON.parse(raw);
      if (typeof value === 'string') return value;
    } catch {
      // Report one stable frontmatter error below.
    }
    throw new Error(`${source}: invalid quoted frontmatter value`);
  }
  if (raw.startsWith("'")) {
    if (!raw.endsWith("'") || raw.length < 2)
      throw new Error(`${source}: invalid quoted frontmatter value`);
    return raw.slice(1, -1).replace(/''/g, "'");
  }
  if (raw.endsWith('"') || raw.endsWith("'"))
    throw new Error(`${source}: invalid quoted frontmatter value`);
  return raw;
}

export function parseSkill(file: string, source: string): Skill {
  // A Windows checkout has CRLF. The model gets the same bytes from every build.
  const text = file.replace(/\r\n/g, '\n');
  const match = text.match(FRONTMATTER);
  if (!match) throw new Error(`${source}: SKILL.md must start with YAML frontmatter`);

  const fields = new Map<string, string>();
  for (const line of match[1].split('\n')) {
    const separator = line.indexOf(':');
    if (separator < 1) throw new Error(`${source}: invalid frontmatter line`);
    const key = line.slice(0, separator).trim();
    const raw = line.slice(separator + 1).trim();
    if (!['name', 'trigger', 'description'].includes(key) || fields.has(key) || !raw)
      throw new Error(`${source}: frontmatter must contain only name, trigger and description`);
    fields.set(key, scalar(raw, source));
  }

  const name = fields.get('name') ?? '';
  const trigger = fields.get('trigger');
  const description = fields.get('description');
  const directory = source.replace(/\\/g, '/').split('/').at(-2) ?? '';
  if (!SKILL_NAME.test(name) || name.length > 64 || name !== directory)
    throw new Error(`${source}: name must match its lowercase hyphenated directory`);
  if (trigger === undefined && description === undefined)
    throw new Error(`${source}: a skill needs a trigger, a description or both`);
  if (trigger !== undefined && (!TRIGGER.test(trigger) || trigger.length > 64))
    throw new Error(`${source}: trigger must be lowercase words joined by underscores`);
  if (description !== undefined && (/[\r\n]/.test(description) || encoder.encode(description).length > 300))
    throw new Error(`${source}: description must be one line of at most 300 UTF-8 bytes`);

  const body = text.slice(match[0].length).replace(/^\n+/, '').trimEnd();
  if (!body) throw new Error(`${source}: skill body is empty`);
  if (encoder.encode(body).length > SKILL_TEXT_LIMIT)
    throw new Error(`${source}: skill body exceeds 16 KiB`);

  return {
    name,
    ...(trigger === undefined ? {} : { trigger }),
    ...(description === undefined ? {} : { description }),
    text: body,
  };
}

// Sorted by name, as the app expects them; at most one skill per trigger,
// since the app adds the one its event names.
export function loadSkills(files: Record<string, string>): Skill[] {
  const skills = Object.entries(files).map(([source, text]) => parseSkill(text, source));
  skills.sort((left, right) => left.name < right.name ? -1 : left.name > right.name ? 1 : 0);
  for (let index = 1; index < skills.length; index += 1)
    if (skills[index - 1].name === skills[index].name)
      throw new Error(`duplicate skill name: ${skills[index].name}`);
  const triggers = new Set<string>();
  for (const skill of skills) {
    if (skill.trigger === undefined) continue;
    if (triggers.has(skill.trigger)) throw new Error(`two skills share the trigger ${skill.trigger}`);
    triggers.add(skill.trigger);
  }
  return skills;
}
// The replies an assistant offers to tap. Its instructions tell it to end a
// message with one line, "Choices: first | second | third"; the page draws
// that line as chips instead of text. A message without it is just text, and
// the person types their answer.
//
// The model does not always break the line: "Set it to 0.6? Choices: Yes |
// Not yet" is the same offer, so the choices are read from the last line
// wherever "Choices:" starts a word in it.

import type { WireMessage } from './bridge/protocol';

const CHOICES = /(^|\s)Choices:(.*)$/;
// While streaming: the end of the text that is, or may yet become, "Choices:".
const PARTIAL = /(^|\s)(C(h(o(i(c(e(s(:.*)?)?)?)?)?)?)?)$/;

function lastLine(text: string): { before: string; line: string } {
  const trimmed = text.trimEnd();
  const cut = trimmed.lastIndexOf('\n');
  return { before: trimmed.slice(0, cut + 1), line: trimmed.slice(cut + 1) };
}

// A finished message: its text without the choices, and the choices.
export function splitChoices(text: string): { body: string; choices: string[] } {
  const { before, line } = lastLine(text);
  const found = CHOICES.exec(line);
  if (!found) return { body: text, choices: [] };
  const choices = found[2]
    .split('|')
    .map((choice) => choice.trim())
    .filter(Boolean);
  return { body: (before + line.slice(0, found.index)).trimEnd(), choices };
}

// The choices the chat waits on: the newest message's, once it is a finished
// reply that offers some. Any later message, the person's own included,
// answers them.
export function openChoices(messages: readonly WireMessage[]): string[] {
  const newest = messages[messages.length - 1];
  return newest?.role === 'assistant' && newest.state === 'complete' ? splitChoices(newest.text).choices : [];
}

// A message still streaming: the same text, minus an end that is, or may yet
// become, the choices, so it never shows as text first.
export function withoutPartialChoices(text: string): string {
  const { before, line } = lastLine(text);
  const found = CHOICES.exec(line) ?? PARTIAL.exec(line);
  return found ? (before + line.slice(0, found.index)).trimEnd() : text;
}

